//! Finite actual original normal-role budget; not native/16GB or speed acceptance.
use mycity_core::{housing,timeline::Command as T,transaction::{Action,Caller,Envelope}};
use mycity_headless::{normal_pool,sim_client::Client,sim_host::{Command,Event}};use mycity_storage::Store;use serde_json::{json,Value};use std::{fs,fs::OpenOptions,io::Write,path::{Path,PathBuf},time::Duration};
#[path="../../../tests/fixtures/service-delivery/opening.rs"]mod fixture;
fn apply(s:&mut Store,a:Action,caller:Caller)->Envelope{let(scope,rev)=s.engine().unwrap().world().scope_revision();let e=Envelope{world:scope.world(),branch:scope.branch(),operation_id:s.committed_sequence()+1,expected_revision:rev,actions:vec![a]};assert!(s.execute(caller,e.clone()).unwrap().model.is_ok());e}
fn event(c:&mut Client,p:&Path)->Event{let e=c.next(Duration::from_secs(15)).unwrap();writeln!(OpenOptions::new().create(true).append(true).open(p.join("events.jsonl")).unwrap(),"{}",serde_json::to_string(&e).unwrap()).unwrap();e}
fn copy(src:&Path,dst:&Path){fs::create_dir(dst).unwrap();for f in fs::read_dir(src).unwrap(){let f=f.unwrap();let to=dst.join(f.file_name());if f.file_type().unwrap().is_dir(){copy(&f.path(),&to)}else{fs::copy(f.path(),&to).unwrap();assert_eq!(fs::read(f.path()).unwrap(),fs::read(to).unwrap());}}}
#[test]fn actual_service_normal_role_and_cold_retry_keep_original_resource_budget(){let root=PathBuf::from(std::env::var_os("MYCITY_SERVICE_DELIVERY_ROOT").unwrap()).canonicalize().unwrap();assert!(root.starts_with("/Volumes/HP P900/dev/MyCity/work"));let p=root.join(format!("normal-role-{}",std::process::id()));fs::create_dir(&p).unwrap();let pool_root=PathBuf::from(std::env::var_os("MYCITY_SERVICE_POOL_ROOT").unwrap());assert!(pool_root.parent().unwrap().canonicalize().unwrap().starts_with("/Volumes/HP P900/dev/MyCity/work"));assert!(!pool_root.exists());let exe=PathBuf::from(std::env::var_os("MYCITY_SERVICE_HEADLESS_EXE").unwrap()).canonicalize().unwrap();let rules=format!("sim-w3:{}",env!("MYCITY_SOURCE_SHA256"));let input=serde_json::to_vec(&fixture::input()).unwrap();fs::write(p.join("opening.json"),&input).unwrap();let world=p.join("world");let mut spatial:Value=serde_json::from_slice(include_bytes!("../../../fixtures/m0-exchange-spatial.json")).unwrap();spatial["bootstrap"]["seed"]=json!(107);let spatial=serde_json::to_vec(&spatial).unwrap();fs::write(p.join("spatial-opening.json"),&spatial).unwrap();let mut s=Store::create_spatial_v2(&world,&input,fixture::resources(),&rules,&spatial,include_bytes!("../../../fixtures/terrain/m0-flat16.png")).unwrap();apply(&mut s,Action::Timeline{command:T::Enable},Caller::System);let offer:housing::GenesisLeaseOffer=serde_json::from_value(fixture::input()["housing"]["lease_offers"][0].clone()).unwrap();apply(&mut s,Action::HousingLease{offer_id:901,offer_sha256:housing::genesis_lease_offer_sha256(offer)},Caller::Account(2));for _ in 0..256{let t=s.engine().unwrap().timeline().unwrap().progress;if t.target.is_none()&&t.last_complete==28800{break;}apply(&mut s,Action::Timeline{command:T::Advance{target:28800,limit:256}},Caller::System);}apply(&mut s,Action::ServiceDelivery{command:mycity_core::service_delivery_authority::Command::Accept{household:7,crew:1}},Caller::Account(3));s.checkpoint().unwrap();drop(s);copy(&world,&p.join("reference"));let mut reference=Store::open(&p.join("reference"),&rules).unwrap();let mut pool=normal_pool::Process::spawn(&exe,&pool_root,Some(&p.join("pool-heaps.jsonl"))).unwrap();let mut observations=vec![];let mut c=Client::new();c.start_in_pool(&exe,&world,false,false,&pool_root).unwrap();let ready=event(&mut c,&p);assert_eq!(ready.kind,"ready");observations.push(serde_json::to_value(ready).unwrap());let mut id=1u64;let mut last=None;
 for target in[29160,33900]{for _ in 0..512{let progress=reference.engine().unwrap().timeline().unwrap().progress;if progress.target.is_none()&&progress.last_complete==target{break;}let(scope,rev)=reference.engine().unwrap().world().scope_revision();let e=Envelope{world:scope.world(),branch:scope.branch(),operation_id:reference.committed_sequence()+1,expected_revision:rev,actions:vec![Action::Timeline{command:T::Advance{target,limit:256}}]};c.submit(id,Command::Execute{envelope:e.clone()}).unwrap();id+=1;let out=event(&mut c,&p);assert!(out.payload["Ok"]["model"].get("Ok").is_some(),"{out:?}");assert!(reference.execute(Caller::System,e.clone()).unwrap().model.is_ok());last=Some(e);}
 c.submit(id,Command::Status).unwrap();id+=1;observations.push(serde_json::to_value(event(&mut c,&p)).unwrap());if target==29160{c.stop().unwrap();let restored=Store::open(&world,&rules).unwrap();assert_eq!(restored.state_hash().unwrap(),reference.state_hash().unwrap());drop(restored);c=Client::new();c.start_in_pool(&exe,&world,false,false,&pool_root).unwrap();let ready=event(&mut c,&p);assert_eq!(ready.kind,"ready");observations.push(serde_json::to_value(ready).unwrap());}}
 c.stop().unwrap();let mut restored=Store::open(&world,&rules).unwrap();assert_eq!(restored.engine().unwrap().export_checkpoint().unwrap(),reference.engine().unwrap().export_checkpoint().unwrap());let seq=restored.committed_sequence();assert!(restored.execute(Caller::System,last.unwrap()).unwrap().model.is_ok());assert_eq!(restored.committed_sequence(),seq);let v=restored.engine().unwrap().service_needs_summary().unwrap().delivery.unwrap();assert_eq!(v.trips[0].motion,mycity_core::service_delivery_authority::Motion::Finished);assert_eq!(v.trips[0].wages_paid,[1700,1700,0,0]);let mut peak=0;
 for e in &observations{let v=e["payload"].get("Ok").unwrap_or(&e["payload"]);let a=&v["runtime"]["allocator_boundary"]["snapshot"];assert_eq!(a["activation"]["grant_bytes"],59*1024*1024);assert_eq!(a["allocation_failures"],0);let used=a["arena_used_bytes"].as_u64().unwrap();assert!(used<=a["arena_usable_bytes"].as_u64().unwrap());peak=peak.max(used);}
 let balance=normal_pool::status(&pool_root).unwrap();assert_eq!(balance.workspace_grants,2);assert_eq!(balance.workspace_returns,2);assert_eq!(balance.available_touched_bytes,64*1024*1024);pool.finish().unwrap();fs::write(p.join("observations.json"),serde_json::to_vec_pretty(&observations).unwrap()).unwrap();fs::write(p.join("resources.json"),serde_json::to_vec_pretty(&json!({"arena_used_observed_max":peak,"engine_owned_bytes":restored.engine().unwrap().owned_capacity_bytes(),"store_owned_bytes":restored.owned_capacity_bytes().unwrap(),"pool":balance,"reference_and_creator_outside_shipping_role":true,"not_native_16gb_speed_or_m0_acceptance":true})).unwrap()).unwrap();}
